        string? keyword = null, priority = null;
        bool? done = null;

        switch (filterAction)
        {
            case "Not Done":
                done = false;
                break;
            case "Done":
                done = true;
                break;
            case "By Priority":
                priority = AnsiConsole.Prompt(
                    new SelectionPrompt<string>()
                        .Title("Priority:")
                        .AddChoices("P0-Critical", "P1-High", "P2-Medium", "P3-Low"));
                break;
            case "By Keyword":
                keyword = AnsiConsole.Ask<string>("Search keyword:");
