                        keyword: keyword, priority: priority, done: done,
                        cancellationToken: cancellationToken);

                    if (result?.Items == null || result.Items.Count == 0)
                    {
                        AnsiConsole.MarkupLine("[yellow]No TODOs found matching the filter.[/]");
