                    table.AddColumn("[green]Title[/]");
                    table.AddColumn("[green]Priority[/]");
                    table.AddColumn("[green]Section[/]");
                    table.AddColumn("[green]Done[/]");

                    foreach (var item in result.Items)
                    {
