+                continue;
+            }
+
+            if (rawLine.StartsWith("signature:", StringComparison.Ordinal))
+            {
+                currentSection = "signature";
+                continue;
+            }
+
+            if (currentSection is not null && rawLine.StartsWith("  ", StringComparison.Ordinal))
+            {
